'use strict';
const fs=require('node:fs'),path=require('node:path');
const S=require('./cleanup-schema.cjs'),B=require('./cleanup-backend.cjs'),F=require('./fixtures.cjs');
const root=process.env.PUBLIC_TEST_TMP_ROOT||process.env.RUNNER_TEMP;S.need(root&&fs.existsSync(root));
const temp=()=>fs.mkdtempSync(path.join(root,'recovery-reader-'));
function incomplete(f){for(const [id,m]of f.items)if(m.name.includes('-lease_bind-')||m.name.includes('-lease-j777-ack')){f.items.delete(id);f.raws.delete(id);}return f;}
async function source(){const f=incomplete(F.fixture(temp(),{mode:'terminal',reconcile:true}));return {f,source:await B.readTarget(f.c,f.deps)};}
function witness(s){
 const d=s.records.deployment.details,j=s.records.jit.details,now=new Date(),expiry=new Date(now.getTime()+25000);
 const p={evidence_version:3,registry_version:4,registry_digest:'ce7726373109617d75c04e5027d8a9ea131c3868d069345d358cad9f96741dbf',registry_provenance:'https://github.com/cosmos/chain-registry/blob/cc1ed04b31326bc79f3208e571fb71fa0fddb987/akash/chain.json',registry_provenance_digest:'3720728bb01b964132cf1452678c6aaf20f0f5b2df098e2d56ceb577e741b1c2',chain_id:'akashnet-2',source_ids:['allnodes','polkachu'],height:100,block_hash:'A'.repeat(64),block_time:now.toISOString(),creation_height:99,creation_block_hash:'B'.repeat(64),creation_block_time:now.toISOString(),creation_txhash:'C'.repeat(64),creation_tx_index:0,owner:d.owner,dseq:'1234567',gseq:'1',group:d.group_population[0].name,groups:d.group_population,population_count:1,population_digest:'f'.repeat(64),observed_at:now.toISOString(),evaluated_at:now.toISOString(),expires_at:expiry.toISOString(),creation_manifest_version:d.expected_manifest_version,current_manifest_version:d.expected_manifest_version};
 const t={schema:S.TARGET,owner:d.owner,dseq:'1234567',returned_runner_id:j.runner_id,group_population:d.group_population,jit_ack_record_sha256:S.hash(s.records.jit),deployment_unknown_record_sha256:S.hash(s.records.deployment),expected_manifest_version:d.expected_manifest_version,precreate_baseline_sha256:S.hash(d.precreate_baseline),creation_identity:S.identity(p)};
 return S.witness(s,{schema:S.WITNESS,actor:s.actor,producer:s.producer,source_bundle_sha256:S.hash(s),target:t,console_snapshot_sha256:'3'.repeat(64),creation_proof:p,authority:'READONLY_DERIVATION'});
}
function effect(c,b,kind,phase='NO_WIRE',parent=null){const t=b.target,e=b.derivation;return S.record({schema:S.OPERATION,operation_id:S.slot(c.actor.target_locator)+'-'+kind,kind,phase,phase_index:{NO_WIRE:0,UNKNOWN:1,ACK:2}[phase],parent_record_sha256:parent,actor:c.actor,producer:b.producer,target:t,target_sha256:S.hash(t),derivation_evidence:{artifact_id:e.artifact_id,artifact_digest:e.artifact_digest,record_sha256:e.body_sha256},details:{owner:t.owner,dseq:t.dseq,group_population:t.group_population,returned_runner_id:t.returned_runner_id,source_record_sha256:t[kind==='close'?'deployment_unknown_record_sha256':'jit_ack_record_sha256'],...(phase==='ACK'?{response_received:true}:{})},authority:'candidate'}).record;}
async function prepared(){const x=await source(),w=witness(x.source);return {...x,w,bundle:await B.admitDerived(x.f.c,x.source,w,x.f.deps)};}
async function heldIntents(f,b){const held=[];for(const kind of ['close','remove']){const r=effect(f.c,b,kind),a=await B.persist(r,f.c,b,held,f.deps);S.ack(a,r);held.push({record:r,artifact_id:a.artifact_id,artifact_digest:a.artifact_digest,body_sha256:S.hash(r)});}return held;}
function nextActor(f){const oldRun=f.runs.get(f.c.actor.run_id),oldJob=f.jobMap.get(f.c.actor.job_id);oldRun.status='completed';oldRun.conclusion='failure';oldJob.status='completed';oldJob.conclusion='failure';oldJob.steps[0].status='completed';oldJob.steps[0].conclusion='failure';oldJob.steps[0].completed_at='2026-10-24T16:00:00Z';const c=F.current('terminal');c.actor.run_id=34567;c.actor.job_id=889;f.runs.set(c.actor.run_id,F.run(c.actor));f.jobMap.set(c.actor.job_id,F.job(c.actor,c.runner_name));return c;}

module.exports={source,witness,effect,incomplete,prepared,heldIntents,nextActor};
